=== src/main/resources/db/migration/V1__sheet.sql
-- A sheet's own settings. A sheet with no row here has never been changed: its today is the real date.
CREATE TABLE sheet (
    id         VARCHAR(255) PRIMARY KEY,
    today_date DATE NOT NULL
);
=== src/main/resources/db/migration/V2__person.sql
-- The people on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255) NOT NULL,
    name     VARCHAR(255) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
=== src/main/resources/db/migration/V3__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case. Names are stored without
-- surrounding spaces; name_key is the lower-cased name the uniqueness is kept on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(255) GENERATED ALWAYS AS (LOWER(name));
ALTER TABLE person ADD CONSTRAINT person_sheet_name UNIQUE (sheet_id, name_key);
=== src/main/resources/officefloor/escalation/net.officefloor.hq.app.person.InvalidPersonException.yml
handle:
  class: net.officefloor.hq.app.person.HandleInvalidPerson
=== src/main/resources/officefloor/escalation/net.officefloor.hq.app.person.PersonNotFoundException.yml
handle:
  class: net.officefloor.hq.app.person.HandlePersonNotFound
=== src/main/resources/officefloor/escalation/net.officefloor.hq.app.sheet.InvalidTodayException.yml
handle:
  class: net.officefloor.hq.app.sheet.HandleInvalidToday
=== src/main/resources/officefloor/rest/api/sheets/{sheetId}/people.GET.yml
# GET /api/sheets/{sheetId}/people — the sheet's people, in the order they were added.
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
=== src/main/resources/officefloor/rest/api/sheets/{sheetId}/people.POST.yml
# POST /api/sheets/{sheetId}/people — add a person. Body {"name":"...","grade":"A|B|C"}. A blank
# name or another grade is refused with 400 and nothing is stored.
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: add
  govern: [ transaction ]
add:
  class: net.officefloor.hq.app.person.AddPerson
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
=== src/main/resources/officefloor/rest/api/sheets/{sheetId}/today.PUT.yml
# PUT /api/sheets/{sheetId}/today — change the sheet's today. Body {"today":"yyyy-mm-dd"}; blank is
# the real date. A date that is not real is refused with 400 and nothing is stored.
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: apply
  govern: [ transaction ]
apply:
  class: net.officefloor.hq.app.sheet.ApplyToday
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]
=== src/main/resources/officefloor/rest/api/sheets/{sheetId}/people/{personId}.PUT.yml
# PUT /api/sheets/{sheetId}/people/{personId} — edit a person. Body as for an add; refused the same
