package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of sheets. A sheet never stored is an empty sheet whose today is the real date. */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        List<LocalDate> today = jdbc.query("SELECT today_date FROM sheet WHERE id = ?",
                (rs, n) -> rs.getObject(1, LocalDate.class), id);
        return new Sheet(id, today.isEmpty() ? LocalDate.now() : today.get(0));
    }

    /** The sheet's today: use this, never the real clock, for anything that depends on the date. */
    public LocalDate today(String id) {
        return find(id).today();
    }

    public void save(Sheet sheet) {
        jdbc.update("MERGE INTO sheet (id, today_date) KEY (id) VALUES (?, ?)", sheet.id(), sheet.today());
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSheet {
    // A sheet that was never loaded before starts empty, so any id loads.
    public void load(@PathVariable("sheetId") String sheetId, Sheets sheets, Out<Sheet> sheetOut) {
        sheetOut.set(sheets.find(sheetId.trim()));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateToday {

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    // Blank takes the default: the real date.
    public LocalDate validate(@RequestBody TodayRequest body) throws InvalidTodayException {
        String raw = body == null || body.today() == null ? "" : body.today().trim();
        if (raw.isEmpty()) {
            return LocalDate.now();
        }
        try {
            return LocalDate.parse(raw, ISO);
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException("Not a date (yyyy-mm-dd): " + raw);
        }
    }
}

